insert into public.categories (id, name, slug, description, sort_order) values
  ('11111111-1111-4111-8111-111111111111', 'Sofas', 'sofas', 'Deep comfort with sculptural silhouettes.', 1),
  ('22222222-2222-4222-8222-222222222222', 'Chairs', 'chairs', 'Accent seating made to linger in.', 2),
  ('33333333-3333-4333-8333-333333333333', 'Tables', 'tables', 'Honest materials for everyday rituals.', 3),
  ('44444444-4444-4444-8444-444444444444', 'Bedroom', 'bedroom', 'Quiet, grounding pieces for restful rooms.', 4),
  ('55555555-5555-4555-8555-555555555555', 'Storage', 'storage', 'Beautiful order for considered homes.', 5)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, sort_order = excluded.sort_order;

insert into public.products (
  id, category_id, name, slug, short_description, description, price_inr, compare_at_price_inr,
  primary_image_url, image_urls, materials, dimensions, featured, in_stock, is_published
) values
  ('a1111111-1111-4111-8111-111111111111', '11111111-1111-4111-8111-111111111111', 'Aaranya Three-Seater Sofa', 'aaranya-three-seater-sofa', 'A softly curved sofa in deep olive performance velvet.', 'The Aaranya sofa balances generous comfort with a tailored silhouette. Its kiln-dried hardwood frame, deep seat and softly rounded arms make it an inviting anchor for modern living rooms.', 78900, 84900, '/assets/products/sofa-olive.svg', array['/assets/products/sofa-olive.svg'], array['Hardwood frame', 'Performance velvet', 'High-resilience foam'], '220 × 96 × 78 cm', true, true, true),
  ('a2222222-2222-4222-8222-222222222222', '22222222-2222-4222-8222-222222222222', 'Noor Bouclé Lounge Chair', 'noor-boucle-lounge-chair', 'A cocooning lounge chair with warm walnut legs.', 'Designed as a quiet retreat, the Noor chair pairs tactile ivory bouclé with a supportive curved back and hand-finished walnut legs.', 32900, null, '/assets/products/chair-boucle.svg', array['/assets/products/chair-boucle.svg'], array['Bouclé upholstery', 'Walnut legs', 'Moulded foam'], '82 × 84 × 76 cm', true, true, true),
  ('a3333333-3333-4333-8333-333333333333', '33333333-3333-4333-8333-333333333333', 'Meher Oval Coffee Table', 'meher-oval-coffee-table', 'Low, organic and beautifully grained solid walnut.', 'The Meher table is shaped with softened edges and two substantial pedestal legs. Each top celebrates the natural variation of responsibly sourced walnut.', 26900, 29900, '/assets/products/table-walnut.svg', array['/assets/products/table-walnut.svg'], array['Solid walnut', 'Natural hardwax oil'], '130 × 68 × 38 cm', true, true, true),
  ('a4444444-4444-4444-8444-444444444444', '44444444-4444-4444-8444-444444444444', 'Saanjh Oak Bed', 'saanjh-oak-bed', 'A restful solid-oak bed with a woven cane headboard.', 'Saanjh brings lightness to the bedroom through rounded oak rails and a hand-woven cane panel. The platform construction keeps the profile calm and grounded.', 64900, null, '/assets/products/bed-oak.svg', array['/assets/products/bed-oak.svg'], array['Solid oak', 'Natural cane', 'Water-based finish'], 'Queen: 214 × 168 × 108 cm', true, true, true),
  ('a5555555-5555-4555-8555-555555555555', '55555555-5555-4555-8555-555555555555', 'Riya Cane Console', 'riya-cane-console', 'A slender entry console with airy cane-front drawers.', 'Riya keeps keys, correspondence and everyday essentials beautifully organised without feeling visually heavy.', 23900, null, '/assets/products/console-cane.svg', array['/assets/products/console-cane.svg'], array['Mango wood', 'Natural cane', 'Brass pulls'], '120 × 40 × 82 cm', false, true, true),
  ('a6666666-6666-4666-8666-666666666666', '33333333-3333-4333-8333-333333333333', 'Viraj Six-Seater Dining Table', 'viraj-six-seater-dining-table', 'A generous walnut table for long, unhurried meals.', 'Viraj combines a softly chamfered top with sculptural trestle legs, leaving generous legroom and a clear, architectural profile.', 58900, 62900, '/assets/products/dining-walnut.svg', array['/assets/products/dining-walnut.svg'], array['Walnut veneer', 'Solid walnut edging'], '200 × 95 × 75 cm', false, true, true),
  ('a7777777-7777-4777-8777-777777777777', '55555555-5555-4555-8555-555555555555', 'Ira Fluted Sideboard', 'ira-fluted-sideboard', 'Fluted doors and a rich forest-green lacquer finish.', 'The Ira sideboard makes storage feel intentional, with adjustable shelving behind four subtly fluted doors.', 45900, null, '/assets/products/sideboard-green.svg', array['/assets/products/sideboard-green.svg'], array['Engineered hardwood', 'Oak veneer', 'Metal base'], '180 × 45 × 76 cm', false, false, true),
  ('a8888888-8888-4888-8888-888888888888', '22222222-2222-4222-8222-222222222222', 'Mitti Round Ottoman', 'mitti-round-ottoman', 'A versatile rust-toned ottoman with a tailored seam.', 'Mitti works as an extra seat, a soft footrest or an informal coffee-table companion. Its compact form fits easily into layered spaces.', 12900, null, '/assets/products/ottoman-rust.svg', array['/assets/products/ottoman-rust.svg'], array['Textured weave', 'Plywood frame', 'High-density foam'], '72 × 72 × 42 cm', false, true, true)
on conflict (id) do update set
  category_id = excluded.category_id, name = excluded.name, slug = excluded.slug,
  short_description = excluded.short_description, description = excluded.description,
  price_inr = excluded.price_inr, compare_at_price_inr = excluded.compare_at_price_inr,
  primary_image_url = excluded.primary_image_url, image_urls = excluded.image_urls,
  materials = excluded.materials, dimensions = excluded.dimensions, featured = excluded.featured,
  in_stock = excluded.in_stock, is_published = excluded.is_published;
